CAT = "cparegIncome"; SEG = "INC"
Q = [
("Which item is excluded from an individual's gross income?",
 "Life insurance paid at death", ["Punitive damages awarded", "Unemployment compensation", "Prize money from a contest"],
 "Life insurance proceeds paid because of the insured's death are excluded. Punitive damages, unemployment benefits and prizes are taxable."),
("Interest on which investment is generally excluded from federal gross income?",
 "A city's general obligation bond", ["A U.S. Treasury bond", "A corporate bond", "A bank certificate of deposit"],
 "Interest on state and local bonds is generally exempt from federal tax. Treasury interest is federally taxable, though exempt from state tax."),
("An employer provides $150,000 of group-term life insurance to an employee. The employee is taxed on the cost of the coverage above:",
 "$50,000", ["$100,000", "$25,000", "$150,000"],
 "The cost of the first $50,000 of employer-provided group-term life coverage is excluded. The cost of coverage over $50,000 is taxable wages."),
("A degree candidate receives a scholarship covering $12,000 of tuition, $1,000 of required books and $6,000 of room and board. Her gross income from it is:",
 "$6,000", ["$0", "$7,000", "$19,000"],
 "A qualified scholarship excludes tuition and required fees, books and supplies. Room and board is taxable, so $6,000 is included."),
("Jo receives $80,000 in a lawsuit for a physical injury: $50,000 compensatory and $30,000 punitive damages. Her gross income includes:",
 "$30,000", ["$0", "$50,000", "$80,000"],
 "Compensatory damages for physical injury are excluded. Punitive damages are taxable even when the injury was physical."),
("Last year Ali itemized, deducted state income tax and got the full tax benefit. This year he receives a $700 refund of that state tax. He includes:",
 "$700", ["$0", "$350", "Only interest on it"],
 "Under the tax benefit rule a recovery of an amount deducted with a tax benefit is income in the year received. The full benefit means all $700 is included."),
("Which receipt is excluded from the recipient's gross income?",
 "A cash gift from a parent", ["A bonus from an employer", "Interest on a savings account", "A prize from a radio contest"],
 "Gifts are excluded from the recipient's income. Any gift tax is the donor's concern."),
("A general partner receives a $60,000 guaranteed payment and a $20,000 share of the partnership's ordinary income. Her self-employment income from it is:",
 "$80,000", ["$60,000", "$20,000", "$0"],
 "A general partner's share of ordinary business income and guaranteed payments for services are both self-employment income: $60,000 + $20,000."),
("A freelancer is paid in virtual currency worth $9,000 at the time for services. She includes in gross income:",
 "$9,000 of ordinary income", ["$9,000 of capital gain", "Nothing until she sells", "$4,500 of ordinary income"],
 "Virtual currency received for services is ordinary income at its fair market value when received, and that value becomes her basis."),
("Bo bought virtual currency for $4,000 and 8 months later used it to buy a laptop priced at $6,500. Bo has:",
 "A $2,500 short-term gain", ["A $2,500 long-term gain", "No gain until year end", "$6,500 of ordinary income"],
 "Virtual currency is property, so spending it is a sale. The $2,500 gain is short-term because it was held a year or less."),
("An investor buys stock on March 10, Year 1. To get long-term capital gain treatment, the earliest sale date is:",
 "March 11, Year 2", ["March 10, Year 2", "January 1, Year 2", "September 11, Year 1"],
 "Long-term treatment needs a holding period of more than one year. The period starts the day after purchase, so a sale on March 11, Year 2 qualifies."),
("A 45-year-old takes $20,000 from a traditional IRA funded only with deductible contributions, and no exception applies. She reports:",
 "$20,000 income plus a 10% tax", ["$20,000 income, no extra tax", "No income, only a 10% tax", "$2,000 of income only"],
 "The whole distribution is ordinary income because she has no basis, and an early distribution before age 59 1/2 also carries the 10% additional tax."),
("The largest share of social security benefits that can be included in gross income is:",
 "85%", ["50%", "100%", "65%"],
 "Depending on provisional income, 0%, up to 50% or up to 85% of benefits are taxable. No more than 85% is ever included."),
("A 25% partner's share of the partnership's long-term capital gain is reported on her Form 1040:",
 "As a long-term capital gain", ["As ordinary business income", "As tax-exempt income", "As a guaranteed payment"],
 "Capital gains are separately stated on the K-1 and keep their character on the partner's return, where they are netted with her other capital transactions."),
("A partner's share of partnership ordinary income is $30,000, but he received only $10,000 in cash during the year. He reports:",
 "$30,000", ["$10,000", "$20,000", "$40,000"],
 "Partners are taxed on their distributive share of income whether or not it is distributed. Cash distributions reduce basis but are not income here."),
("A single-member LLC owned by an individual has made no entity election. Its business income is reported on:",
 "Schedule C of Form 1040", ["Form 1065", "Form 1120-S", "Form 1120"],
 "A single-member LLC is disregarded by default, so a sole owner reports its business income on Schedule C."),
("Alimony received under a divorce decree executed in 2022 is:",
 "Not included in income", ["Fully included in income", "Half included in income", "Included above a floor"],
 "For divorce or separation instruments executed after 2018, alimony is neither deductible by the payer nor included in the recipient's income."),
("Wages a decedent earned but that were paid to the estate after death are:",
 "Income in respect of a decedent", ["Reported on the final 1040", "Excluded from all income", "A gift to the estate"],
 "Amounts earned but not received before death are income in respect of a decedent, taxed to the estate or beneficiary who receives them, not on the final return."),
("Which employer-provided benefit is taxable to the employee?",
 "A cash-equivalent gift card", ["Employer health insurance", "A holiday turkey", "Occasional coffee and snacks"],
 "Cash and cash equivalents such as gift cards are never de minimis fringe benefits, whatever the amount. Health coverage and small occasional items are excluded."),
("Which item must be included in an individual's gross income?",
 "Unemployment compensation", ["Workers' compensation", "Child support received", "An inheritance of cash"],
 "Unemployment compensation is fully taxable. Workers' compensation, child support and inheritances are excluded."),
]
